<?php
namespace App\Modules\Customer\Infrastructure\Persistence;
use App\Models\CustomerAddress;use App\Modules\Customer\Domain\Contracts\AddressRepositoryInterface;use App\Modules\Customer\Domain\Exceptions\AddressNotFoundException;use Illuminate\Support\Facades\DB;
final class EloquentAddressRepository implements AddressRepositoryInterface{public function listForUser(int $userId):iterable{return CustomerAddress::query()->where('user_id',$userId)->latest()->get();}public function defaultForUser(int $userId):?CustomerAddress{return CustomerAddress::query()->where('user_id',$userId)->where('is_default',true)->first();}public function findForUser(int $userId,int $addressId):CustomerAddress{$address=CustomerAddress::query()->where('user_id',$userId)->whereKey($addressId)->first();if(!$address)throw new AddressNotFoundException('Address not found.');return $address;}public function createForUser(int $userId,array $data):CustomerAddress{return DB::transaction(function()use($userId,$data){$hasAddress=CustomerAddress::query()->where('user_id',$userId)->exists();if(($data['is_default']??false)||!$hasAddress)CustomerAddress::query()->where('user_id',$userId)->update(['is_default'=>false]);$data['user_id']=$userId;$data['is_default']=($data['is_default']??false)||!$hasAddress;return CustomerAddress::query()->create($data);});}public function update(object $address,array $data):CustomerAddress{return DB::transaction(function()use($address,$data){if($data['is_default']??false)CustomerAddress::query()->where('user_id',$address->user_id)->where('id','!=',$address->id)->update(['is_default'=>false]);$address->update($data);return $address->fresh();});}public function delete(object $address):void{DB::transaction(function()use($address){$wasDefault=$address->is_default;$userId=$address->user_id;$address->delete();if($wasDefault){$replacement=CustomerAddress::query()->where('user_id',$userId)->latest('id')->first();if($replacement)$replacement->update(['is_default'=>true]);}});}}
